static int can_produce_colorless(int player, int card)
{
  return get_card_instance(player, card)->card_color & 0x41;
}

static int spectacle_paid(int player, int card)
{
  return get_card_instance(player, card)->info_slot & 2;
}

static watermark_t get_watermark(card_instance_t *inst)
{
  return get_watermark_by_iid(inst->internal_card_id < 0
                                  ? inst->original_internal_card_id
                                  : inst->internal_card_id);
}

static int is_dark_outdoors(void)
{
  unsigned int now = (unsigned int)localtime_hour_minute();
  unsigned int hour = now >> 16;
  unsigned int minute = now & 0xffffU;
  if (hour == 5)
    return minute <= 29;
  if (hour == 18)
    return minute > 29;
  return hour < 5 || hour > 18;
}

static int has_sp_key_by_iid(int iid, int sp_key)
{
  return has_sp_key_by_csvid_impl(cards_data[iid].id, sp_key);
}

static void release_dynamic_card_type(iid_t dynamic_iid)
{
  if (dynamic_iid >= engine_dynamic_iid_start &&
      dynamic_iid <= engine_dynamic_iid_start + 15)
    cards_data[dynamic_iid].id = 0xffff;
}

static int is_tribal_by_id(int player, int csvid)
{
  return has_subtype_by_id(player, csvid, SUBTYPE_TRIBAL);
}

static int is_vehicle_or_dwarf(int player, int iid)
{
  return has_subtype_by_id(player, cards_data[iid].id, SUBTYPE_DWARF) ||
         has_subtype_by_id(player, cards_data[iid].id, SUBTYPE_VEHICLE);
}

static int any_left_in_packs(int **packs, int num_opponents)
{
  for (int i = 0; i <= num_opponents; ++i)
    if (packs[i][0] >= 0)
      return 1;
  return 0;
}

static int raw_has_subtype(csvid_t csvid, subtype_t subt)
{
  const card_ptr_t *cp = cards_ptr[csvid];
  for (int i = 0; i < 7; ++i)
    if (cp->types[i] == subt)
      return 1;
  return 0;
}

static int allow_duplicates(EXPANSION_t expansion, csvid_t csvid)
{
  switch (csvid)
  {
    case CARD_ID_FOREST:
    case CARD_ID_ISLAND:
    case CARD_ID_MOUNTAIN:
    case CARD_ID_PLAINS:
    case CARD_ID_SWAMP:
      return 1;
    default:
      return (unsigned int)(csvid - CARD_ID_SNOW_COVERED_FOREST) <= 4U &&
             expansion == EXPANSION_ICE_AGE;
  }
}

static PartyBit_t party_bits(int player, int card)
{
  if (get_card_instance(player, card)->internal_card_id < 0 ||
      !is_what(player, card, TYPE_CREATURE))
    return PARTY_NONE;
  unsigned int bits = PARTY_NONE;
  if (has_subtype(player, card, SUBTYPE_CLERIC))
    bits |= PARTY_CLERIC;
  if (has_subtype(player, card, SUBTYPE_ROGUE))
    bits |= PARTY_ROGUE;
  if (has_subtype(player, card, SUBTYPE_WARRIOR))
    bits |= PARTY_WARRIOR;
  if (has_subtype(player, card, SUBTYPE_WIZARD))
    bits |= PARTY_WIZARD;
  return (PartyBit_t)bits;
}

static void count_party_classes(int player, int *num_candidates,
                                int *candidates_by_class)
{
  for (int i = 0; i < 16; ++i)
    candidates_by_class[i] = 0;
  *num_candidates = 0;
  for (int card = 0; card < active_cards_count[player]; ++card)
  {
    if (!in_play(player, card))
      continue;
    PartyBit_t bits = party_bits(player, card);
    if (bits != PARTY_NONE)
    {
      ++candidates_by_class[bits];
      ++*num_candidates;
    }
  }
}

static int has_ability_counters(int player, int card)
{
  /* Extra counter slots share the final target entry in the native layout. */
  const unsigned char *p = (const unsigned char *)get_card_instance(player, card);
  return (p[0x51] >= COUNTER_DEATHTOUCH && p[0x51] <= COUNTER_VIGILANCE && p[0]) ||
         (p[0x104] >= COUNTER_DEATHTOUCH && p[0x104] <= COUNTER_VIGILANCE && p[1]) ||
         (p[0x105] >= COUNTER_DEATHTOUCH && p[0x105] <= COUNTER_VIGILANCE && p[2]) ||
         (p[0x106] >= COUNTER_DEATHTOUCH && p[0x106] <= COUNTER_VIGILANCE && p[3]) ||
         (p[0x107] >= COUNTER_DEATHTOUCH && p[0x107] <= COUNTER_VIGILANCE && p[0x121]) ||
         (p[0x10a] >= COUNTER_DEATHTOUCH && p[0x10a] <= COUNTER_VIGILANCE && p[0x108]) ||
         (p[0x10b] >= COUNTER_DEATHTOUCH && p[0x10b] <= COUNTER_VIGILANCE && p[0x109]);
}

static int imprint_legacymatches(card_instance_t *instance, int player, int card)
{
  return instance->internal_card_id == LEGACY_EFFECT_CUSTOM &&
         instance->info_slot_fn == imprint_legacy && in_play(player, card) &&
         instance->damage_source_player == player && instance->damage_source_card == card;
}

static void counters_on_upkeep(int player, int card, event_t event, int counter_type)
{
  upkeep_trigger_ability_mode(player, card, event, player, RESOLVE_TRIGGER_DUH);
  if (event == EVENT_UPKEEP_TRIGGER_ABILITY)
    add_counter(player, card, player, card, (counter_t)counter_type);
}

